  .membership-panel { padding: 26px; }
  h1 { font-size: clamp(52px, 6.7vw, 70px); }
  .museum-facts { grid-template-columns: 1fr; gap: 30px; }
  .facts-heading h2 { max-width: none; }
}
@media (max-width: 767px) {
  .wrap { width: calc(100% - 40px); }
